class Solution {
public:
    int countDays(int days, vector<vector<int>>& meetings) {
        sort(meetings.begin(), meetings.end());
        int n = meetings.size();
        long long covered = 0;
        int curStart = meetings[0][0];
        int curEnd = meetings[0][1];
        for (int i = 1; i < n; i++) {
            if (meetings[i][0] <= curEnd) {
                curEnd = max(curEnd, meetings[i][1]);
            } else {
                covered += (long long)(curEnd - curStart + 1);
                curStart = meetings[i][0];
                curEnd = meetings[i][1];
            }
        }
        covered += (long long)(curEnd - curStart + 1);
        return days - (int)covered;
    }
};
